// eval/corpus.json -> eval/chunks.json (+ eval/articles.md, a map for writing eval questions)
//
//   npm run chunks
import fs from 'node:fs';
import { chunkArticle } from '../src/core/chunker.js';
import { CHUNKS_PATH, loadCorpus } from '../src/core/corpus.js';
import type { Chunk } from '../src/core/types.js';

const articles = loadCorpus();
const all: Chunk[] = [];
const rows: Record<string, string | number>[] = [];
const md: string[] = [
  '# Article map',
  '',
  'Generated by `npm run chunks`. Use it to write eval questions: pick a section,',
  'then ask about it in your own words (do not copy phrases from the article).',
  '',
];

for (const a of articles) {
  const chunks = chunkArticle(a);
  all.push(...chunks);

  const warnings: string[] = [];
  if (chunks.length === 0) warnings.push('NO CHUNKS (empty content?)');
  if (chunks.length && chunks.every(c => !c.headingId)) warnings.push('no headings');
  if (chunks.some(c => c.wordCount > 450)) warnings.push('very long chunk');
  const total = chunks.reduce((s, c) => s + c.wordCount, 0);
  rows.push({
    slug: a.slug,
    chunks: chunks.length,
    words: total,
    maxChunk: Math.max(0, ...chunks.map(c => c.wordCount)),
    warnings: warnings.join('; '),
  });

  md.push(`## ${a.title}`, '', `slug: \`${a.slug}\` · language: ${a.language} · ${total} words`, '');
  for (const c of chunks) {
    const preview = c.text.replace(/\s+/g, ' ').slice(0, 90);
    const also = c.mergedHeadings.length
      ? ` (also contains: ${c.mergedHeadings.map(h => `\`${h.headingId}\``).join(', ')})`
      : '';
    md.push(
      `- #${c.index} \`${c.headingId || '(intro)'}\` ${c.heading} (${c.wordCount} words)${also}: ${preview}…`,
    );
  }
  md.push('');
}

fs.writeFileSync(CHUNKS_PATH, JSON.stringify({ count: all.length, chunks: all }, null, 2));
fs.writeFileSync('eval/articles.md', md.join('\n'));

console.table(rows);
const words = all.map(c => c.wordCount).sort((x, y) => x - y);
console.log(
  `\n${articles.length} articles -> ${all.length} chunks. ` +
    `Words per chunk: min ${words[0] ?? 0}, median ${words[Math.floor(words.length / 2)] ?? 0}, max ${words[words.length - 1] ?? 0}`,
);
console.log(`Wrote ${CHUNKS_PATH} and eval/articles.md`);
